import sys

def main():
    d = sys.stdin.read().split()
    n, p = int(d[0]), int(d[1])
    a = list(map(int, d[2:2 + n]))
    for i in range(min(p, n)):
        m = i
        for j in range(i + 1, n):
            if a[j] < a[m]:
                m = j
        a[i], a[m] = a[m], a[i]
    print(' '.join(map(str, a)))

