def gen(rng):
    def fmt(a, p):
        return str(len(a)) + ' ' + str(p) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5], 0), fmt([5], 1), fmt([2, 2, 2], 2), fmt([3, 1, 1, 2], 2), fmt([1, 2, 3, 4], 3),
             fmt([4, 3, 2, 1], 4), fmt([-5, 10**9, -10**9, 0], 2), fmt([1, 1, 0, 0, 0], 3)]
    for n in (2, 3, 5, 8, 12, 20):
        for _ in range(3):
            hi = rng.choice([3, 9, 99])
            a = [rng.randint(-hi, hi) for _ in range(n)]
            tests.append(fmt(a, rng.randint(0, n)))
    big = 2000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(big)], big))
    tests.append(fmt([rng.randint(-5, 5) for _ in range(big)], big // 2))
    tests.append(fmt(list(range(big, 0, -1)), big))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(big)], 1500))
    return tests

